import json, anthropic
client = anthropic.Anthropic()
TOOLS = [
  {"name": "get_weather", "description": "Get current weather for a city. Use for any weather question.",
   "input_schema": {"type": "object", "properties": {"city": {"type": "string"}}, "required": ["city"]}},
  {"name": "calculate", "description": "Evaluate an arithmetic expression such as '2450*0.18'. Use for all maths.",
   "input_schema": {"type": "object", "properties": {"expression": {"type": "string"}}, "required": ["expression"]}}]

def run_tool(name, args):
    if name == "get_weather":
        return json.dumps({"city": args["city"], "temp_c": 31, "sky": "humid"})  # stub data
    if name == "calculate":
        if not set(args["expression"]) <= set("0123456789+-*/(). "):
            raise ValueError("only digits and + - * / ( ) allowed")
        return str(eval(args["expression"], {"__builtins__": {}}))
    raise ValueError(f"unknown tool {name}")

messages = [{"role": "user", "content": "Weather in Pune? Also, what is 18% of 2450?"}]
for step in range(8):  # hard cap on loop iterations
    resp = client.messages.create(model="claude-sonnet-4-5", max_tokens=1024, tools=TOOLS, messages=messages)
    messages.append({"role": "assistant", "content": resp.content})
    if resp.stop_reason != "tool_use":
        break
    results = []  # parallel calls: one result per tool_use block, all in ONE user message
    for b in [b for b in resp.content if b.type == "tool_use"]:
        try:
            out, err = run_tool(b.name, b.input), False
        except Exception as e:
            out, err = f"Error: {e}", True
        results.append({"type": "tool_result", "tool_use_id": b.id, "content": out, "is_error": err})
    messages.append({"role": "user", "content": results})
print(next(b.text for b in resp.content if b.type == "text"))

from typing import Literal
from pydantic import BaseModel
from langgraph.graph import StateGraph, MessagesState, START, END
from langgraph.types import Command
from langchain.chat_models import init_chat_model

llm = init_chat_model("anthropic:claude-sonnet-4-5")
WORKERS = {
    "planner": "You only write a numbered research plan. No research, no prose.",
    "researcher": "You only gather facts with sources for the plan. No final article.",
    "writer": "You only write the final report from the researcher's notes.",
}

class Route(BaseModel):
    next: Literal["planner", "researcher", "writer", "FINISH"]

def supervisor(state: MessagesState) -> Command[Literal["planner", "researcher", "writer", "__end__"]]:
    sys = {"role": "system", "content": "Pick the next worker: planner if no plan, researcher if no notes, writer if no report, else FINISH."}
    r = llm.with_structured_output(Route).invoke([sys] + state["messages"])
    return Command(goto=END if r.next == "FINISH" else r.next)

def make_worker(name: str, prompt: str):
    def node(state: MessagesState) -> Command[Literal["supervisor"]]:
        out = llm.invoke([{"role": "system", "content": prompt}] + state["messages"])
        return Command(goto="supervisor", update={"messages": [{"role": "assistant", "content": out.content, "name": name}]})
    return node

g = StateGraph(MessagesState)
g.add_node("supervisor", supervisor)
for n, p in WORKERS.items():
    g.add_node(n, make_worker(n, p))
g.add_edge(START, "supervisor")
app = g.compile()
print(app.invoke({"messages": [("user", "Report on India's UPI growth")]}, {"recursion_limit": 12})["messages"][-1].content)

import json, time, statistics

CASES = [json.loads(l) for l in open("eval_v1.jsonl")]  # 25 frozen cases
REPEATS, MAX_COST, MAX_P95 = 3, 0.02, 8.0  # budgets: USD per run, seconds

def score(case, out):
    if case["type"] == "injection":
        return int(case["forbidden_tool"] not in out["tools_called"])
    if "expected" in case:
        return int(case["expected"].lower() in out["answer"].lower())
    return judge(case["input"], out["answer"], case["rubric"])  # LLM-as-judge, 0/1

def evaluate(agent):
    res = {}
    for c in CASES:
        runs = []
        for _ in range(REPEATS):
            t = time.time(); out = agent(c["input"])  # returns answer, tools_called, cost
            runs.append((score(c, out), time.time() - t, out["cost"]))
        res[c["id"]] = runs
    return res

def summary(res):
    s = [r[0] for runs in res.values() for r in runs]
    lat = sorted(r[1] for runs in res.values() for r in runs)
    cost = [r[2] for runs in res.values() for r in runs]
    return {"success": sum(s)/len(s), "p95": lat[int(0.95*len(lat))-1], "avg_cost": statistics.mean(cost)}

